    12	/** Thin wrapper around the points vendor CLI (vendor/bin/ptsctl). One process per call. */
    13	public class PtsctlClient {
    14	    /** One line of the vendor history: entry number, our reference, points. */
    15	    public record HistoryRow(String entryNo, String ref, long points) {}
    16	
    17	    private final Path bin;
    18	    private final Path home;
    19	    private final long timeoutSeconds;
    20	
    21	    public PtsctlClient(Path bin, Path home, long timeoutSeconds) {
    22	        this.bin = bin;
    23	        this.home = home;
    24	        this.timeoutSeconds = timeoutSeconds;
    25	    }
    26	
    27	    /** Credits points to a member; returns the vendor entry number. */
    28	    public String earn(String memberNo, long points, String ref) {
    29	        return run(List.of("earn", "--mbr", memberNo, "--pt", Long.toString(points), "--ref", ref)).strip();
    30	    }
    31	
    32	    public long balance(String memberNo) {
    33	        String out = run(List.of("bal", memberNo)).strip();
    34	        String[] t = out.split("\\s+");
    35	        if (t.length != 2) throw new PtsException("unexpected bal reply: " + out);
    36	        return Long.parseLong(t[1]);
    37	    }
    38	
    39	    public List<HistoryRow> history(String memberNo) {
    40	        List<HistoryRow> rows = new ArrayList<>();
    41	        for (String line : run(List.of("hist", memberNo)).split("\n")) {
    42	            if (line.isBlank()) continue;
    43	            String[] f = line.split("\t");
    44	            if (f.length != 3) throw new PtsException("unexpected hist line: " + line);
    45	            rows.add(new HistoryRow(f[0], f[1], Long.parseLong(f[2])));
    46	        }
    47	        return rows;
    48	    }
