    27	        List<Payment> out = new ArrayList<>();
    28	        for (String[] r : rows(file)) {
    29	            out.add(new Payment(r[0], cell(r[1]), r[2], Long.parseLong(r[3]), r[4]));
    30	        }
    31	        return out;
    32	    }
    33	
    34	    /**
    35	     * The acquirer's payment export is made for spreadsheets: member numbers that start
    36	     * with 0 are written as ="004512" so the spreadsheet keeps them as text.
    37	     */
    38	    static String cell(String raw) {
    39	        String s = raw.strip();
    40	        if (s.startsWith("=\"") && s.endsWith("\"") && s.length() >= 3) {
    41	            return s.substring(2, s.length() - 1);
    42	        }
    43	        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
    44	            return s.substring(1, s.length() - 1);
    45	        }
    46	        return s;
    47	    }
    48	
    49	    private static List<String[]> rows(Path file) {
    50	        try {
    51	            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
    52	            List<String[]> rows = new ArrayList<>();
    53	            for (int i = 1; i < lines.size(); i++) {
    54	                String l = lines.get(i).strip();
    55	                if (!l.isEmpty()) rows.add(l.split(",", -1));
    56	            }
    57	            return rows;
    58	        } catch (IOException e) {
    59	            throw new IllegalStateException("cannot read " + file, e);
    60	        }
    61	    }
    62	}
